				"gearDescription_8": { "quality": 1, "name": "An old padded vest, its cotton filling unevenly distributed. Some long-forgotten emblem has been worn away.", "keywords": ["gear_1"] },
				"gearDescription_9": { "quality": 1, "name": "A lumpy and ill-fitting padded coat, more suited for warmth than battle.", "keywords": ["gear_1"] },
				"gearDescription_10": { "quality": 1, "name": "A sweat-stained gambeson with uneven stitching. A crude [MOTIF] has been added in an attempt to personalize it.", "keywords": ["gear_1"] },
				"gearDescription_11": { "quality": 2, "name": "A simple padded vest, slightly worn but still functional. The fabric holds together well.", "keywords": ["gear_1"] },
				"gearDescription_12": { "quality": 2, "name": "A serviceable gambeson, showing minor wear. A stitched [MOTIF] stands out against the plain fabric.", "keywords": ["gear_1"] },
				"gearDescription_13": { "quality": 2, "name": "A modest padded tunic, with minor fraying along the seams. A subtle [MOTIF] is embroidered into the chest.", "keywords": ["gear_1"] },
				"gearDescription_14": { "quality": 2, "name": "A durable quilted vest, lightly stained from use.", "keywords": ["gear_1"] },
				"gearDescription_15": { "quality": 2, "name": "A thickly padded gambeson, reinforced at the shoulders. A faded [MOTIF] is stitched along the neckline.", "keywords": ["gear_1"] },
				"gearDescription_16": { "quality": 2, "name": "A reliable padded coat, slightly discolored from exposure.", "keywords": ["gear_1"] },
				"gearDescription_17": { "quality": 2, "name": "A worn but sturdy quilted tunic, reinforced at key points. A skillfully embroidered [MOTIF] enhances its look.", "keywords": ["gear_1"] },
				"gearDescription_18": { "quality": 2, "name": "A modest but well-maintained padded vest, its surface adorned with a stitched [MOTIF].", "keywords": ["gear_1"] },
				"gearDescription_19": { "quality": 2, "name": "A practical quilted gambeson, offering decent protection.", "keywords": ["gear_1"] },
				"gearDescription_20": { "quality": 2, "name": "A sturdy padded tunic, its fabric slightly faded from repeated use. The sleeves are decorated with a faint [MOTIF].", "keywords": ["gear_1"] },
				"gearDescription_21": { "quality": 3, "name": "A well-made padded tunic, comfortable and durable. The chest proudly displays a finely stitched [MOTIF].", "keywords": ["gear_1"] },
				"gearDescription_22": { "quality": 3, "name": "A carefully woven gambeson, offering good protection.", "keywords": ["gear_1"] },
				"gearDescription_23": { "quality": 3, "name": "A durable and balanced padded vest, its fabric reinforced.", "keywords": ["gear_1"] },
				"gearDescription_24": { "quality": 3, "name": "A quality padded coat, lined with wool for comfort. The back features a prominently displayed [MOTIF].", "keywords": ["gear_1"] },
				"gearDescription_25": { "quality": 3, "name": "A standard but well-maintained padded tunic, with a bold [MOTIF] adorning the chest.", "keywords": ["gear_1"] },
